CREATE COLUMN TABLE "TEST_AP"."OTRX" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(20) NOT NULL , "Descr" NVARCHAR(250), "Type" NVARCHAR(8) DEFAULT 'XSLT', "Data" BLOB MEMORY THRESHOLD 1000, PRIMARY KEY ("AbsEntry")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTRX_CODE" ON "TEST_AP"."OTRX" ( "Code" ASC )